var questions=[["冬天多出半小时，你最想？", ["泡杯热饮慢慢喝", "出门看看落日", "给朋友发一句问候", "把床边收拾得舒服一点"]], ["今天最想留住哪个瞬间？", ["捧着杯子的温度", "路边树枝上的光", "有人记得我的小事", "房间终于整整齐齐"]], ["挑一件小礼物，你会选？", ["喜欢的杯子", "一本随身小相册", "可以一起玩的桌游", "一盏床头小灯"]], ["哪种冬日安排更吸引你？", ["试一种新的热饮搭配", "走一条不同的回家路", "和熟人吃一顿热饭", "给自己的角落换个布置"]], ["如果写一句当天记录，你想写？", ["今天喝到了喜欢的味道", "今天发现了一处好看的光影", "今天和某个人聊得很开心", "今天把生活照顾好了"]], ["明天你愿意先做哪件小事？", ["留十分钟慢慢喝点热的", "出门留意一处冬日风景", "主动联系一个想念的人", "整理一个常用的小角落"]]];var results=[["喝点热的，慢慢来", "你刚才选了不少和味道、温度有关的小事。", "今天找一只顺手的杯子，泡点家里现有的热饮。坐下来喝完，给自己留十分钟。", "下面还有几个小点子，挑一个顺眼的就好。"], ["去有光的地方走走", "你刚才更想看看外面的风景。", "趁白天出门走一小段，留意树影、落叶，或者今天的天空。天太冷，就在窗边晒会儿太阳。", "不用走远，楼下也可能有好看的冬天。"], ["找个人，吃顿热饭", "你刚才选了好几次和人相处的小事。", "约一位相处舒服的人，吃顿热饭，聊聊最近发生的事。没空见面，发条消息也行。", "不用安排一整天，一碗面也能坐着聊很久。"], ["把自己的小窝弄暖和", "你刚才更想把身边的小地方照顾好。", "收拾床边的一小块，打开一盏灯，把毯子放在手边。忙完以后，就能在这里坐一会儿。", "只收一小块就行，剩下的改天再说。"]];